-- Q4403: Related Party Transactions [hard/L2]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["$50,000 capital gain at preferential tax rates","$50,000 Section 1231 gain with recapture potential","$50,000 ordinary income under Sec. 1239 and 707(b)","$50,000 tax-exempt gain excluded from gross income"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (C): The taxpayer owns more than 50% of the partnership, making them related parties. Under Section 1239, gain on the sale of depreciable property to a related party is ordinary income. Section 707(b) independently recharacterizes the gain as ordinary when the property is non-capital to the partnership.
Wrong (A): Capital gain treatment is unavailable because Sec. 1239 converts gain on depreciable property sold to a related party to ordinary income.
Wrong (B): Section 1231 treatment is overridden by the specific related-party rules in Sec. 1239 and 707(b).
Wrong (D): There is no exemption for gain on property sales between related parties; the gain is fully taxable as ordinary income.$EXPL$
WHERE id = 4403;

-- Q4975: Multi-Jurisdictional Tax Planning [medium/L2]
