-- Q4981: Multi-Jurisdictional Tax Planning [hard/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Assigns nowhere sales to the state of shipment origin","Removes nowhere sales from both numerator and denominator of the sales factor","Eliminates the sales factor entirely, using only property and payroll","Applies only to sales of services, not tangible personal property"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (B): A throwout rule removes nowhere sales from both the numerator and denominator of the sales factor, which increases the apportionment percentage in taxing states. This differs from a throwback rule, which assigns nowhere sales to the state of origin.
